// C++: src/primitive_core.cc toit::primitive_remove_finalizer
Object *primitive_remove_finalizer(Process *process, Object **__args)
/*@ requires [?f]process(process, ?prog, ?ids) &*& heap(?objs, ?H) &*& pointer(__args, ?key) &*&
             good(objs, key) == true &*& registered_callbacks(process_heap_address(process), ?entries); @*/
/*@ ensures [f]process(process, prog, ids) &*& pointer(__args, key) &*&
            heap(objs, removes(process, H, key) ? change_flag(H, key, -32) : H) &*&
            registered_callbacks(process_heap_address(process), removes(process, H, key) ? without_key(entries, key) : entries) &*&
            (is_heap_w((uword)key) ? result == process_boolean(process, removes(process, H, key)) :
              (uword)result == 4 * Program_WRONG_OBJECT_TYPE_INDEX + 3); @*/
{
  //@ error_word(Program_WRONG_OBJECT_TYPE_INDEX);
  Object *_raw_object = __args[-(0)];
  if (!is_heap_object(_raw_object)) {
    return (Object *)((uword)((int)(Program_WRONG_OBJECT_TYPE_INDEX) << Error_ERROR_SHIFT) | Error_ERROR_TAG);
  }
  HeapObject *object = HeapObject_cast__Objectp(_raw_object);
  //@ good_heap(objs, key);
  if (HeapObject_on_program_heap(object, process)) {
    return ((false) ? Process_true_object(process) : Process_false_object(process));
  }
  if (!is_instance(object)) {
    return ((false) ? Process_true_object(process) : Process_false_object(process));
  }
  //@ heap_open(object);
  //@ normal_flag_header(object);
  bool result = HeapObject_has_active_finalizer(object);
  //@ open flag_header(object, _, _);
  //@ close header(object, o_hw(H(object)));
  //@ heap_close(object);
  if (result) {
    ObjectHeap_remove_callable_finalizer(Process_object_heap(process), Instance_cast(object));
  }
  return ((result) ? Process_true_object(process) : Process_false_object(process));
}

// C++: src/primitive_core.cc toit::primitive_add_finalizer
Object *primitive_add_finalizer(Process *process, Object **__args)
/*@ requires [?f]process(process, ?prog, ?ids) &*& heap(?objs, ?H) &*& pointer(__args, ?key) &*&
             pointer(__args - 1, ?callback) &*& good(objs, key) == true &*& good(objs, callback) == true &*&
             registered_callbacks(process_heap_address(process), ?entries); @*/
/*@ ensures [f]process(process, prog, ids) &*& pointer(__args, key) &*& pointer(__args - 1, callback) &*&
            heap(objs, ?H2) &*& registered_callbacks(process_heap_address(process), ?after) &*&
            addition_out(process, H, ids, key, callback, entries, H2, after, result) == true; @*/
{
  //@ error_word(Program_WRONG_OBJECT_TYPE_INDEX);
  //@ error_word(Program_ALREADY_EXISTS_INDEX);
  //@ error_word(Program_MALLOC_FAILED_INDEX);
  Object *_raw_object = __args[-(0)];
  if (!is_heap_object(_raw_object)) {
    return (Object *)((uword)((int)(Program_WRONG_OBJECT_TYPE_INDEX) << Error_ERROR_SHIFT) | Error_ERROR_TAG);
  }
  HeapObject *object = HeapObject_cast__Objectp(_raw_object);
  Object *finalizer = __args[-(1)];
  //@ good_heap(objs, key);
  //@ heap_facts(key);
  bool make_weak = false;
  if (!HeapObject_can_be_toit_finalized(object, Process_program(process))) {
    if (!is_instance(object) || HeapObject_class_id(Instance_cast(object)) != Program_map_class_id(Process_program(process))) {
      return (Object *)((uword)((int)(Program_WRONG_OBJECT_TYPE_INDEX) << Error_ERROR_SHIFT) | Error_ERROR_TAG);
    }
    make_weak = true;
  }
  // ASSERT(is_instance(object)): release build, not evaluated.
  if (!HeapObject_on_program_heap(object, process)) {
    //@ heap_open(key);
    //@ normal_flag_header(key);
    bool already_active = HeapObject_has_active_finalizer(object);
    //@ open flag_header(key, _, _);
    //@ close header(key, o_hw(H(key)));
    //@ heap_close(key);
    if (already_active) {
      return (Object *)((uword)((int)(Program_ALREADY_EXISTS_INDEX) << Error_ERROR_SHIFT) | Error_ERROR_TAG);
    }
    if (!ObjectHeap_add_callable_finalizer(Process_object_heap(process), Instance_cast(object), finalizer, make_weak)) {
      return (Object *)((uword)((int)(Program_MALLOC_FAILED_INDEX) << Error_ERROR_SHIFT) | Error_ERROR_TAG);
    }
  }
  return Process_null_object(process);
}

